/**
 * Federal funds from USAspending, as generated by scripts/usaspending into
 * data/generated/usaspending-pr.json. The site never calls USAspending:
 * everything here comes from that committed file.
 *
 * Geographic states (see scripts/usaspending/source.ts):
 *   MUNICIPIO_ATTRIBUTABLE  the only money painted on the map
 *   MUNICIPIO_UNCERTAIN     recorded in a municipio, but it may serve the whole island
 *   PUERTO_RICO_STATEWIDE   assistance for all of Puerto Rico, no municipio
 *   NO_MUNICIPIO_GEOGRAPHY  contracts with no municipio
 * The four add up to the Puerto Rico total.
 */
import funds from "../../../data/generated/usaspending-pr.json";
import { dayLabel as formatDay } from "../../i18n/format.ts";
import type { Locale } from "../../i18n/locale.ts";
import { FUNDS_MESSAGES } from "../../i18n/messages/funds.ts";

export type GeoState =
  | "MUNICIPIO_ATTRIBUTABLE"
  | "MUNICIPIO_UNCERTAIN"
  | "PUERTO_RICO_STATEWIDE"
  | "NO_MUNICIPIO_GEOGRAPHY";
export const GEO_STATE_ORDER: GeoState[] = [
  "MUNICIPIO_ATTRIBUTABLE",
  "MUNICIPIO_UNCERTAIN",
  "PUERTO_RICO_STATEWIDE",
  "NO_MUNICIPIO_GEOGRAPHY",
];

/** Reader-facing names and one-line meanings of the four states. */
export function geoStateCopy(
  locale: Locale = "es",
): Record<GeoState, { label: string; detail: string }> {
  return FUNDS_MESSAGES[locale].geo;
}
export const GEO_STATE_COPY = geoStateCopy("es");

type Ranked = [string, number];
export type MunicipioFunds = {
  name: string;
  recorded: number | null;
  attributable: number | null;
  contracts: number;
  individuals: number;
  uncertain: number;
  award: {
    attributableObligations: number | null;
    attributableOutlays: number | null;
    uncertainObligations: number | null;
    uncertainOutlays: number | null;
  };
  awards: { recorded: number; attributable: number };
  contractAgencies: Ranked[];
  individualPrograms: Ranked[];
  uncertainPrograms: Ranked[];
  history: { attributable: (number | null)[]; uncertain: (number | null)[] };
};

type Funds = {
  source: {
    publisher: string;
    site: string;
    api: string;
    retrievedAt: string;
    retrievedUntil: string;
    sourceLastUpdated: string;
    outlaysReportedThrough: { fiscalYear: number; fiscalMonth: number; periodEnd: string };
    terms: { about: string; dnb: string; apiDocs: string; dataDictionary: string };
    attribution: string;
  };
  fiscalYear: number;
  period: { start: string; end: string };
  history: number[];
  island: {
    total: number;
    states: Record<GeoState, number>;
    statewideIndividuals: number;
    byAwardType: Record<string, number>;
    award: {
      obligations: number;
      outlays: number | null;
      states: Record<GeoState, { obligations: number; outlays: number | null }>;
    };
    awards: { recorded: number };
    agencies: Ranked[];
    programs: Ranked[];
    history: { fiscalYear: number; total: number; states: Record<GeoState, number> }[];
  };
  municipios: Record<string, MunicipioFunds>;
  cdbg: {
    awardId: string;
    obligated: number;
    outlays: number | null;
    start: string | null;
    end: string | null;
  }[];
  names: { agencies: Record<string, string>; programs: Record<string, string> };
};

const data = funds as unknown as Funds;

export const FUNDS_SOURCE = data.source;
export const FUNDS_FY = data.fiscalYear;
export const FUNDS_PERIOD = data.period;
export const FUNDS_HISTORY = data.history;
export const FUNDS_ISLAND = data.island;
export const FUNDS_CDBG = data.cdbg;

/** "2026-10-07" → "7 oct 2026" / "Oct 7, 2026". */
export function dayLabel(iso: string, locale: Locale = "es"): string {
  return formatDay(iso, locale);
}
/** "AF 2026 (1 oct 2025 – 30 sep 2026)" / "FY 2026 (Oct 1, 2025 – Sep 30, 2026)". */
export function fundsFyLabel(locale: Locale = "es"): string {
  return FUNDS_MESSAGES[locale].fiscalYearRange(
    data.fiscalYear,
    dayLabel(data.period.start, locale),
    dayLabel(data.period.end, locale),
  );
}
export const FUNDS_FY_LABEL = fundsFyLabel("es");

export function fundsFor(id: string): MunicipioFunds | null {
  return data.municipios[id] ?? null;
}

export function agencyName(code: string): string {
  return data.names.agencies[code] ?? code;
}
export function programName(code: string): string {
  return data.names.programs[code] ?? code;
}

/** Map values: attributable obligations, attributable reported outlays, attributable award count. */
export function fundsValues(): Record<
  string,
  { obligations: number | null; outlays: number | null; awards: number | null }
> {
  return Object.fromEntries(
    Object.entries(data.municipios).map(([id, m]) => [
      id,
      {
        obligations: m.attributable,
        outlays: m.award.attributableOutlays,
        awards:
          m.attributable === null && m.award.attributableObligations === null
            ? null
            : m.awards.attributable,
      },
    ]),
  );
}

export { money } from "./money";
